WITH gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) > INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_session FROM payments), sessions_payments AS (SELECT id, order_id, paid_at, status, SUM(is_new_session) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT id, order_id, paid_at, status, CASE WHEN status RLIKE '^(FAILED|REFUNDED)$' THEN 'GROUP_A' WHEN status RLIKE '^(SUCCESS)$' THEN 'OTHER_ZONE' ELSE 'GROUP_B' END AS status_zone FROM sessions_payments ORDER BY paid_at DESC NULLS FIRST
